import{_ as n}from"./chunks/verwaltung-schule-vorschau.CVL_UyyH.js";import{_ as r,o as t,c as a,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const p=JSON.parse('{"title":"Schuldaten und Programmstand in der Vorschau prüfen","description":"","frontmatter":{"title":"Schuldaten und Programmstand in der Vorschau prüfen","source_pageid":287,"source_revision":4004},"headers":[],"relativePath":"schild3/schueler/vorschau-verwaltung-schule.md","filePath":"schild3/schueler/vorschau-verwaltung-schule.md"}'),s={name:"schild3/schueler/vorschau-verwaltung-schule.md"};function u(d,e,l,o,g,c){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="schuldaten-und-programmstand-in-der-vorschau-prufen" tabindex="-1">Schuldaten und Programmstand in der Vorschau prüfen <a class="header-anchor" href="#schuldaten-und-programmstand-in-der-vorschau-prufen" aria-label="Permalink to &quot;Schuldaten und Programmstand in der Vorschau prüfen&quot;">​</a></h1><p>Prüfen Sie Schulname, Kontaktdaten, aktuellen Lernabschnitt und Programmstand. Die Vorschau zeigt vorhandene Angaben an; Änderungen nehmen Sie in den Schuleinstellungen vor.</p><p><a href="/bilder/erste-schritte/verwaltung-schule-vorschau.png"><img src="'+n+'" alt="Schild Verwaltung Schule Vorschau.png" loading="lazy"></a></p><p>Diese Seite wird immer direkt auch geöffnet, wenn der Reiter Verwaltung oder im Reiter Verwaltung der Menüpunkt Schule aufgerufen wird.</p><p>In diesem Fenster können keinerlei Änderungen vorgenommen werden. Hier werden die Informationen angezeigt, welche unter <em>Verwaltung ➜ Schule</em> ➜ <strong>Allgemeine Angaben</strong> eingetragen werden.</p><p>Das Fenster ist in drei Elemente gegliedert:</p><ul><li><strong>Schule</strong>: Hier werden neben dem Schullogo der Name der Schule (in drei Zeilen) und die Schulnummer angezeigt.</li><li><strong>Aktueller Zustand</strong>: Hier steht großformatig das Schuljahr und der Abschnitt, in dem sich die Datenbank gerade befindet. Die weiteren Angaben geben Auskunft über die verwendete SchILD-NRW-Version und die Datenbank. Eventuell werden diese abgefragt, wenn Support in Anspruch genommen werden muss oder zur manuellen Überprüfung, ob eine Aktualisierung des Programms notwendig ist.</li><li><strong>Kontaktdaten</strong>: Hier wird lediglich die Anschrift, die Mailadresse und die Webseite angezeigt. Sofern unter <em>Allgemeine Angaben</em> keine Eintragung gemacht wurde, bleibt hier eine Anzeige aus.</li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Vorschau_(Verwaltung_Schule)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4004.</p>',9)])])}const f=r(s,[["render",u]]);export{p as __pageData,f as default};
